#include <iostream>
#include <iomanip>
#include <string>
#include <limits>
#include <chrono>
#include <random>
#include <algorithm>
#include <cctype>
using namespace std;
struct Student { int id=0; string name,service; int priority=0; };
int number(const string& prompt,int low,int high){int x;while(true){cout<<prompt;if(cin>>x && x>=low && x<=high){cin.ignore(numeric_limits<streamsize>::max(),'\n');return x;}cout<<"Invalid entry. Try again.\n";cin.clear();cin.ignore(numeric_limits<streamsize>::max(),'\n');}}
string line(const string& p){string s;do{cout<<p;getline(cin,s);if(s.find_first_not_of(" \t\r\n")==string::npos)cout<<"Cannot be blank.\n";}while(s.find_first_not_of(" \t\r\n")==string::npos);return s;}
class Registry {struct Node{Student s;Node *prev,*next;explicit Node(const Student&v):s(v),prev(nullptr),next(nullptr){}};Node *head=nullptr,*tail=nullptr;public:Registry()=default;Registry(const Registry&)=delete;Registry&operator=(const Registry&)=delete;~Registry(){clear();}void clear(){while(head){Node*n=head;head=head->next;delete n;}tail=nullptr;}bool add(const Student&s){if(find(s.id))return false;Node*n=new Node(s);if(tail){tail->next=n;n->prev=tail;}else head=n;tail=n;return true;}Student*find(int id){for(Node*n=head;n;n=n->next)if(n->s.id==id)return &n->s;return nullptr;}bool remove(int id,Student&old){for(Node*n=head;n;n=n->next)if(n->s.id==id){old=n->s;if(n->prev)n->prev->next=n->next;else head=n->next;if(n->next)n->next->prev=n->prev;else tail=n->prev;delete n;return true;}return false;}void display()const{cout<<left<<setw(10)<<"ID"<<setw(25)<<"Name"<<setw(24)<<"Service"<<"Priority\n";for(Node*n=head;n;n=n->next)cout<<setw(10)<<n->s.id<<setw(25)<<n->s.name<<setw(24)<<n->s.service<<n->s.priority<<'\n';}int size()const{int c=0;for(Node*n=head;n;n=n->next)++c;return c;}Student* snapshot(int&n)const{n=size();Student*a=new Student[n];int i=0;for(Node*p=head;p;p=p->next)a[i++]=p->s;return a;}};
struct Action{int kind;Student before,after;};
class UndoStack{struct Node{Action a;Node*next;Node(const Action&x,Node*n):a(x),next(n){}};Node*top=nullptr;public:UndoStack()=default;UndoStack(const UndoStack&)=delete;UndoStack&operator=(const UndoStack&)=delete;~UndoStack(){Action a;while(pop(a)){} }void push(const Action&a){top=new Node(a,top);}bool pop(Action&a){if(!top)return false;Node*n=top;a=n->a;top=n->next;delete n;return true;}void show()const{for(Node*n=top;n;n=n->next)cout<<"Action "<<n->a.kind<<" on ID "<<n->a.before.id<<'\n';}void peek()const{if(top)cout<<"Latest action type: "<<top->a.kind<<" ID "<<top->a.before.id<<'\n';else cout<<"History empty.\n";}};
class ServiceQueue{struct Node{int id,priority;Node*next;Node(int i,int p):id(i),priority(p),next(nullptr){}};Node*front=nullptr,*back=nullptr;bool prioritized;public:explicit ServiceQueue(bool p):prioritized(p){}ServiceQueue(const ServiceQueue&)=delete;ServiceQueue&operator=(const ServiceQueue&)=delete;~ServiceQueue(){int x;while(dequeue(x)){} }bool contains(int id)const{for(Node*n=front;n;n=n->next)if(n->id==id)return true;return false;}bool erase(int id){Node*prev=nullptr;Node*n=front;while(n&&n->id!=id){prev=n;n=n->next;}if(!n)return false;if(prev)prev->next=n->next;else front=n->next;if(back==n)back=prev;delete n;return true;}void enqueue(int id,int priority){Node*n=new Node(id,priority);if(prioritized&&front&&priority>front->priority){n->next=front;front=n;return;}if(prioritized){Node*p=front;while(p&&p->next&&p->next->priority>=priority)p=p->next;if(p){n->next=p->next;p->next=n;if(!n->next)back=n;return;}}if(back)back->next=n;else front=n;back=n;}bool dequeue(int&x){if(!front)return false;Node*n=front;x=n->id;front=n->next;if(!front)back=nullptr;delete n;return true;}void peek()const{if(front)cout<<"Next student: "<<front->id<<'\n';else cout<<"Queue empty.\n";}void show()const{for(Node*n=front;n;n=n->next)cout<<n->id<<" (priority "<<n->priority<<") -> ";cout<<"END\n";}};
struct Metrics{long long comparisons=0,swaps=0;double ms=0;};
int compareStudents(const Student&a,const Student&b,int field){if(field==2){if(a.name<b.name)return -1;if(a.name>b.name)return 1;}else if(field==3){if(a.priority<b.priority)return -1;if(a.priority>b.priority)return 1;}else{if(a.id<b.id)return -1;if(a.id>b.id)return 1;}return 0;}
void bubble(Student*a,int n,int field,Metrics&m){for(int i=0;i<n-1;i++){bool changed=false;for(int j=0;j<n-i-1;j++){++m.comparisons;if(compareStudents(a[j],a[j+1],field)>0){swap(a[j],a[j+1]);++m.swaps;changed=true;}}if(!changed)break;}}
void selection(Student*a,int n,int field,Metrics&m){for(int i=0;i<n-1;i++){int k=i;for(int j=i+1;j<n;j++){++m.comparisons;if(compareStudents(a[j],a[k],field)<0)k=j;}if(k!=i){swap(a[i],a[k]);++m.swaps;}}}
// Adjacent-swap insertion sort: every recorded swap is a real exchange.
void insertion(Student*a,int n,int field,Metrics&m){for(int i=1;i<n;i++){int j=i;while(j>0){++m.comparisons;if(compareStudents(a[j-1],a[j],field)<=0)break;swap(a[j-1],a[j]);++m.swaps;--j;}}}
int linear(const Student*a,int n,int key,long long&c){for(int i=0;i<n;i++){++c;if(a[i].id==key)return i;}return -1;}
int binary(const Student*a,int n,int key,long long&c){int l=0,r=n-1;while(l<=r){int mid=l+(r-l)/2;++c;if(a[mid].id==key)return mid;if(a[mid].id<key)l=mid+1;else r=mid-1;}return -1;}
void sortRun(Student*data,int n,int type,int field,Metrics&m){auto start=chrono::steady_clock::now();if(type==1)bubble(data,n,field,m);else if(type==2)selection(data,n,field,m);else insertion(data,n,field,m);m.ms=chrono::duration<double,milli>(chrono::steady_clock::now()-start).count();}
void benchmark(){cout<<"\nAlgorithm        N       Profile       Comparisons       Swaps       ms         Big-O\n";mt19937 rng(105);for(int n:{100,1000,10000,50000})for(int profile=0;profile<3;profile++){Student*base=new Student[n];for(int i=0;i<n;i++)base[i].id=i+1;if(profile==0)shuffle(base,base+n,rng);if(profile==2)reverse(base,base+n);int key=n/2;long long c=0;auto start=chrono::steady_clock::now();linear(base,n,key,c);double ms=chrono::duration<double,milli>(chrono::steady_clock::now()-start).count();auto print=[&](const string&label,long long comparisons,long long swaps,double time,const string&bigO){cout<<left<<setw(17)<<label<<setw(8)<<n<<setw(14)<<(profile==0?"Random":profile==1?"Sorted":"Reverse")<<setw(18)<<comparisons<<setw(12)<<(swaps<0?"N/A":to_string(swaps))<<fixed<<setprecision(4)<<setw(11)<<time<<bigO<<'\n';};print("Linear Search",c,-1,ms,"O(n)");Student*sorted=new Student[n];copy(base,base+n,sorted);sort(sorted,sorted+n,[](const Student&a,const Student&b){return a.id<b.id;});c=0;start=chrono::steady_clock::now();binary(sorted,n,key,c);ms=chrono::duration<double,milli>(chrono::steady_clock::now()-start).count();print("Binary Search",c,-1,ms,"O(log n)*");delete[]sorted;for(int type=1;type<=3;type++){Student*a=new Student[n];copy(base,base+n,a);Metrics m;sortRun(a,n,type,1,m);print(type==1?"Bubble Sort":type==2?"Selection Sort":"Insertion Sort",m.comparisons,m.swaps,m.ms,"O(n^2)");delete[]a;}delete[]base;}cout<<"* Binary search timing excludes the O(n log n) preparation sort.\n";}
Student inputStudent(){Student s;s.id=number("Student ID (1-999999): ",1,999999);s.name=line("Full name: ");s.service=line("Service (Assessing/Clearance/Transcript): ");s.priority=number("Priority (0 regular, 1 graduating, 2 PWD/senior): ",0,2);return s;}
int main(){Registry registry;UndoStack history;ServiceQueue regular(false),priority(true);for(;;){cout<<"\n=== UNIVERSITY STUDENT SERVICE & QUEUE SYSTEM ===\n1 Add student  2 Edit student  3 Delete student  4 List students\n5 Enqueue service  6 Process queue  7 View queues  8 Undo\n9 Search IDs  10 Sort records  11 Benchmark  12 History  0 Exit\n";int op=number("Choice: ",0,12);if(!op)break;if(op==1){Student s=inputStudent();if(registry.add(s)){history.push({1,s,s});cout<<"Added.\n";}else cout<<"Duplicate ID.\n";}else if(op==2){int id=number("ID: ",1,999999);Student*p=registry.find(id);if(!p){cout<<"Not found.\n";continue;}Student old=*p;p->name=line("New name: ");p->service=line("New service: ");p->priority=number("New priority (0-2): ",0,2);regular.erase(id);priority.erase(id);history.push({2,old,*p});cout<<"Updated (previous pending queue ticket, if any, removed; enqueue again).\n";}else if(op==3){int id=number("ID: ",1,999999);Student old;if(registry.remove(id,old)){regular.erase(id);priority.erase(id);history.push({3,old,old});cout<<"Deleted (pending tickets removed).\n";}else cout<<"Not found.\n";}else if(op==4)registry.display();else if(op==5){int id=number("Student ID: ",1,999999);Student*p=registry.find(id);if(!p){cout<<"Student not found.\n";continue;}if(regular.contains(id)||priority.contains(id)){cout<<"Student already queued.\n";continue;}if(p->priority)priority.enqueue(id,p->priority);else regular.enqueue(id,0);cout<<"Queued.\n";}else if(op==6){int id;if(priority.dequeue(id)||regular.dequeue(id))cout<<"Serving student "<<id<<'\n';else cout<<"Both queues empty.\n";}else if(op==7){cout<<"Priority: ";priority.show();cout<<"Regular: ";regular.show();cout<<"Next priority: ";priority.peek();cout<<"Next regular: ";regular.peek();}else if(op==8){Action a;if(!history.pop(a)){cout<<"Nothing to undo.\n";continue;}if(a.kind==1){Student old;registry.remove(a.before.id,old);regular.erase(a.before.id);priority.erase(a.before.id);}else if(a.kind==2){Student*p=registry.find(a.before.id);if(p)*p=a.before;else cout<<"Record missing; update could not be restored.\n";}else if(!registry.add(a.before))cout<<"Could not restore deleted record.\n";cout<<"Undo processed (registry changes only; queue tickets are not restored).\n";}else if(op==9){int n;Student*a=registry.snapshot(n);int id=number("Search ID: ",1,999999);long long c=0;int idx=linear(a,n,id,c);cout<<"Linear: "<<(idx>=0?"Found":"Not found")<<", comparisons="<<c<<'\n';Metrics m;insertion(a,n,1,m);c=0;idx=binary(a,n,id,c);cout<<"Binary (sorted copy): "<<(idx>=0?"Found":"Not found")<<", comparisons="<<c<<'\n';delete[]a;}else if(op==10){int n;Student*a=registry.snapshot(n);int t=number("1 Bubble 2 Selection 3 Insertion: ",1,3);int field=number("Sort field: 1 ID, 2 Name, 3 Priority: ",1,3);Metrics m;sortRun(a,n,t,field,m);cout<<"Sorted records:\n";for(int i=0;i<n;i++)cout<<a[i].id<<" | "<<a[i].name<<" | priority "<<a[i].priority<<'\n';cout<<"Comparisons "<<m.comparisons<<" Swaps "<<m.swaps<<" Time(ms) "<<m.ms<<'\n';delete[]a;}else if(op==11)benchmark();else if(op==12){history.peek();history.show();}}}
